import heapq

def match(orders):
    buy_heap = []   # max-heap for buys: (-price, seq, id)
    sell_heap = []  # min-heap for sells: (price, seq, id)
    book = {}       # id -> dict with side, price, qty, seq, cancelled
    seq_counter = 0
    trades = []

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            if oid in book:
                book[oid]['qty'] = 0
                book[oid]['cancelled'] = True
            continue

        if typ == 'limit':
            _, oid, side, price, qty = o
        elif typ == 'ioc':
            _, oid, side, price, qty = o
        elif typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0 and sell_heap:
                p, s, sid = sell_heap[0]
                info = book.get(sid)
                if info is None or info['qty'] <= 0 or info.get('cancelled'):
                    heapq.heappop(sell_heap)
                    continue
                if price is not None and p > price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([oid, sid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    heapq.heappop(sell_heap)
        else:  # sell
            while remaining > 0 and buy_heap:
                negp, s, bid = buy_heap[0]
                p = -negp
                info = book.get(bid)
                if info is None or info['qty'] <= 0 or info.get('cancelled'):
                    heapq.heappop(buy_heap)
                    continue
                if price is not None and p < price:
                    break
                trade_qty = min(remaining, info['qty'])
                trades.append([bid, oid, p, trade_qty])
                remaining -= trade_qty
                info['qty'] -= trade_qty
                if info['qty'] == 0:
                    heapq.heappop(buy_heap)

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            book[oid] = {'side': side, 'price': price, 'qty': remaining,
                         'seq': seq_counter, 'cancelled': False}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

